729	### Task 3.2 W2: `appendDefLevelsWithLength`
730	
731	- Files: `zig-parquet/src/core/encoding/rle_encoder.zig` (new pub fn + test)
732	- Depends on: 3.1 (same file)
733	- Change: add `const Optional = @import("../types.zig").Optional;` and:
734	
735	```zig
736	/// Append V1 definition levels (bit width 1, u32 length prefix) for a flat
737	/// column straight from its values. Byte-identical to
738	/// `encodeDefLevelsWithLength` on the matching is-defined slice: same run-splitting rule as `encode`.
739	pub fn appendDefLevelsWithLength(comptime T: type, out: *std.ArrayList(u8), allocator: std.mem.Allocator, values: []const Optional(T)) !void {
740	    const len_pos = out.items.len;
741	    try out.appendNTimes(allocator, 0, 4);
742	    const body_start = out.items.len;
743	    const n = values.len;
744	    var i: usize = 0;
745	    while (i < n) {
746	        const d = values[i] != .null_value;
747	        var run_len: usize = 1;
748	        while (i + run_len < n and (values[i + run_len] != .null_value) == d and run_len < 0x7FFFFFFF) run_len += 1;
749	        if (run_len >= 8 or i + run_len == n) {
750	            try writeVarInt(out, allocator, run_len << 1);
751	            try out.append(allocator, @intFromBool(d));
752	            i += run_len;
753	            continue;
754	        }
755	        // Bit-pack until the next run of >= 8, exactly like `encode`.
756	        var pack_count: usize = 0;
757	        var j = i;
758	        while (j < n) {
759	            const dj = values[j] != .null_value;
760	            var next_run: usize = 1;
761	            while (j + next_run < n and (values[j + next_run] != .null_value) == dj) next_run += 1;
762	            if (next_run >= 8) break;
763	            pack_count += next_run;
764	            j += next_run;
765	        }
766	        const count = @min(((pack_count + 7) / 8) * 8, n - i);
767	        const groups = (count + 7) / 8;
768	        try writeVarInt(out, allocator, (groups << 1) | 1);
769	        const start = out.items.len;
770	        try out.appendNTimes(allocator, 0, groups);
771	        for (0..count) |k| {
772	            if (values[i + k] != .null_value) out.items[start + k / 8] |= @as(u8, 1) << @as(u3, @truncate(k)); // k % 8
773	        }
774	        i += count;
775	    }
776	    const body_len = try safe.castTo(u32, out.items.len - body_start);
777	    std.mem.writeInt(u32, out.items[len_pos..][0..4], body_len, .little);
778	}
779	```
