786	### Task 3.3 W3: PLAIN page fast path (fixed width, bool, byte arrays)
787	
788	- Files: `zig-parquet/src/core/page_writer.zig` (`writeDataPageOptionalWithEncoding`,
789	  `writeDataPageByteArrayOptionalWithEncoding`, new private fns, tests)
790	- Depends on: 3.2
791	- Change 1: first line of `writeDataPageOptionalWithEncoding`:
792	  `if (encoding == .plain and (T == i32 or T == i64 or T == f32 or T == f64 or T == bool)) return writePlainPageOptional(allocator, T, values, is_optional);`
793	
794	```zig
795	/// PLAIN page built in one buffer: [u32 len + def levels] (optional only), then
796	/// the non-null values. Byte-identical to the general path.
797	fn writePlainPageOptional(allocator: std.mem.Allocator, comptime T: type, values: []const Optional(T), is_optional: bool) PageWriteError!DataPageResult {
798	    var non_null: usize = 0;
799	    for (values) |v| {
800	        if (v != .null_value) non_null += 1;
801	    }
802	    if (!is_optional and non_null != values.len) return error.NullInRequiredColumn;
803	
804	    const value_bytes = if (T == bool) (non_null + 7) / 8 else std.math.mul(usize, non_null, @sizeOf(T)) catch return error.IntegerOverflow;
805	    var out: std.ArrayList(u8) = .empty;
806	    errdefer out.deinit(allocator);
807	    try out.ensureTotalCapacity(allocator, value_bytes + values.len / 4 + 16);
808	    if (is_optional) try rle_encoder.appendDefLevelsWithLength(T, &out, allocator, values);
809	
810	    const start = out.items.len;
811	    try out.appendNTimes(allocator, 0, value_bytes); // zeroed: bool packing ORs bits in
812	    const dst = out.items[start..];
813	    var k: usize = 0;
814	    for (values) |v| switch (v) {
815	        .null_value => {},
816	        .value => |x| {
817	            if (T == bool) {
818	                if (x) dst[k / 8] |= @as(u8, 1) << @as(u3, @truncate(k)); // k % 8
819	            } else {
820	                const Bits = if (@sizeOf(T) == 4) u32 else u64;
821	                std.mem.writeInt(Bits, dst[k * @sizeOf(T) ..][0..@sizeOf(T)], @bitCast(x), .little);
822	            }
823	            k += 1;
824	        },
825	    };
826	    return .{ .data = try out.toOwnedSlice(allocator), .num_values = values.len, .num_non_null = non_null };
827	}
828	```
