789	/// Path of the input being replayed, printed by the panic handler so a crash names its file.
790	var current_path: []const u8 = "";
791	/// Executions so far; the watchdog calls a hang when it stops moving for `hang_seconds`.
792	var progress = std.atomic.Value(u64).init(0);
793	var hang_seconds: u64 = 10;
794	
795	fn watchdog(io: std.Io) void {
796	    var last = progress.load(.monotonic);
797	    var still: u64 = 0;
798	    while (true) {
799	        io.sleep(.fromNanoseconds(1_000_000_000), .awake) catch return;
800	        const now = progress.load(.monotonic);
801	        still = if (now == last) still + 1 else 0;
802	        last = now;
803	        if (still >= hang_seconds) {
804	            std.debug.print("fuzz-hang: one input ran for over {d}s: {s}\n", .{ hang_seconds, if (current_path.len > 0) current_path else "<out>/current.bin" });
805	            std.process.exit(77);
806	        }
807	    }
808	}
