810	    fn f(msg: []const u8, ra: ?usize) noreturn {
811	        if (current_path.len > 0) std.debug.print("fuzz: crashing input: {s}\n", .{current_path});
812	        std.debug.defaultPanic(msg, ra);
813	    }
814	}.f);
