994	// Seed generation: re-encode every decodable IPC stream in <root>/ipc-stream with zarrow's own
995	// writers (plain, lz4, zstd; stream and file; plus a sliced copy of each batch) so mutations
996	// start from rich, zarrow-produced inputs for every type the readers support.
997	
998	fn genSeeds(gpa: Allocator, io: std.Io, root: []const u8) !void {
999	    var arena_state = std.heap.ArenaAllocator.init(gpa);
1000	    defer arena_state.deinit();
1001	    const a = arena_state.allocator();
1002	    const cwd = std.Io.Dir.cwd();
1003	    const stream_dir = try std.fs.path.join(a, &.{ root, "ipc-stream" });
1004	    const file_dir = try std.fs.path.join(a, &.{ root, "ipc-file" });
1005	    try cwd.createDirPath(io, file_dir);
1006	    var inputs: std.ArrayList([]const u8) = .empty;
1007	    try listInputs(a, io, stream_dir, &inputs);
1008	    var written: usize = 0;
1009	    for (inputs.items) |path| {
1010	        // Only valid sources: skip earlier output and crash reproducers.
1011	        const base = std.fs.path.basename(path);
1012	        if (for ([_][]const u8{ "gen-", "regress-", "at-stream-", "at-tensor-" }) |p| {
1013	            if (std.mem.startsWith(u8, base, p)) break true;
1014	        } else false) continue;
1015	        const bytes = cwd.readFileAlloc(io, path, a, .limited(max_input_len)) catch continue;
1016	        if (runOne(.@"ipc-stream", gpa, bytes).err != null) continue;
1017	        for ([_]?zarrow.IpcBodyCompressionCodec{ null, .lz4_frame, .zstd }) |codec| {
1018	            for ([_]bool{ false, true }) |as_file| {
1019	                const encoded = (if (as_file) transcode(gpa, bytes, codec, true) else transcode(gpa, bytes, codec, false)) catch continue;
1020	                defer gpa.free(encoded);
1021	                const check: Target = if (as_file) .@"ipc-file" else .@"ipc-stream";
1022	                if (runOne(check, gpa, encoded).err != null or encoded.len > 16 << 10) continue;
1023	                const hex = hexName(encoded);
1024	                const name = try std.fmt.allocPrint(a, "{s}/gen-{s}-{s}.bin", .{
1025	                    if (as_file) file_dir else stream_dir,
1026	                    if (codec) |c| @tagName(c) else "plain",
1027	                    hex[0..12],
1028	                });
1029	                try cwd.writeFile(io, .{ .sub_path = name, .data = encoded });
1030	                written += 1;
1031	            }
1032	        }
1033	    }
1034	    std.debug.print("gen-seeds: wrote {d} seeds from {d} inputs\n", .{ written, inputs.items.len });
1035	}
