1037	fn transcode(gpa: Allocator, bytes: []const u8, codec: ?zarrow.IpcBodyCompressionCodec, comptime as_file: bool) ![]u8 {
1038	    var fixed: std.Io.Reader = .fixed(bytes);
1039	    var reader = zarrow.IpcStreamReader.init(gpa, &fixed);
1040	    defer reader.deinit();
1041	    const schema = try reader.readSchema();
1042	    var out: std.Io.Writer.Allocating = .init(gpa);
1043	    errdefer out.deinit();
1044	    const options: zarrow.IpcStreamWriterOptions = .{ .body_compression = codec };
1045	    var writer = if (as_file)
1046	        try zarrow.IpcFileWriter.initWithOptions(gpa, &out.writer, options)
1047	    else
1048	        zarrow.IpcStreamWriter.initWithOptions(gpa, &out.writer, options);
1049	    defer writer.deinit();
1050	    try writer.writeSchema(schema);
1051	    while (try reader.nextRecordBatch()) |batch_value| {
1052	        var batch = batch_value;
1053	        defer batch.deinit();
1054	        try writer.writeRecordBatch(batch);
1055	        if (batch.numRows() > 2 and !as_file) { // sliced batches exercise non-zero offsets
1056	            var sliced = try batch.slice(1, batch.numRows() - 2);
1057	            defer sliced.deinit();
1058	            try writer.writeRecordBatch(sliced);
1059	        }
1060	    }
1061	    try writer.writeEnd();
1062	    return out.toOwnedSlice();
1063	}
